const response = $input.first().json;
const cop = response.rates?.COP || 0;
const eur = response.rates?.EUR || 0;
const fecha = response.time_last_update_utc?.split(' ')?.[0] || new Date().toISOString().split('T')[0];

// Calcular inverso: cuantos COP por 1 USD vs cuantos USD por 1 COP
const usdPorCop = (1 / cop).toFixed(6);

// Calcular tendencia (se necesita historial, placeholder)
const trmFormatted = new Intl.NumberFormat('es-CO', { style: 'decimal', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(cop);

const message = `💵 *TRM — ${fecha}*\n\n💰 *$${trmFormatted} COP* por 1 USD\n💱 1 COP = ${usdPorCop} USD\n🇪🇺 1 USD = ${eur} EUR\n\n📊 *Tasas LATAM:*\n🇲🇽 MXN: ${response.rates?.MXN?.toFixed(2)}\n🇧🇷 BRL: ${response.rates?.BRL?.toFixed(2)}\n🇵🇪 PEN: ${response.rates?.PEN?.toFixed(2)}\n🇨🇱 CLP: ${response.rates?.CLP?.toFixed(0)}\n\n⚡ *TRM Alertas* — Recibe esto todos los días a las 8am`;

return { number: '573106055920', message: message };
